/** A release found without the application naming one. */
export interface InferredServiceVersion {
    version: string;
    /** The environment variable it was read from, or the git directory. */
    source: string;
}
/**
 * The release this process is running, for an application that did not set
 * `serviceVersion`: from the environment first, then from the git checkout
 * the process runs in, then from a container platform's revision name.
 *
 * Never throws - an unreadable file is a release that could not be inferred,
 * not a reason to keep the application from booting.
 */
export declare function inferServiceVersion(env?: NodeJS.ProcessEnv, searchFrom?: (string | undefined)[]): InferredServiceVersion | undefined;
